/**
 * What selection reads: closures over the engine, as state.mjs's Io.
 * @typedef {{ read: (path: string) => Promise<string | null>, exists: (path: string) => Promise<boolean>, list: (path: string) => Promise<{ name: string, kind: string }[]>, sessionId: () => Promise<string> }} PackIo
 */

/** @param {string | null} text */
const json = text => {
  if (!text) return null
  try {
    const value = JSON.parse(text)
    return value && typeof value === 'object' ? value : null
  } catch {
    return null
  }
}

// The default branch a clone knows: where refs/remotes/origin/HEAD points, in the git folder its worktrees share.
// Read from the files, with no git call; '' when it cannot be told.
/** @param {PackIo} io @param {string} root */
const defaultBranchOf = async (io, root) => {
  const named = await gitDirOf(io, root)
  if (!named) return ''
  // A worktree's .git file may name its git folder from the worktree.
  const gitDir = named === `${root}/.git` || isAbsolute(named) ? named : normalFolder(`${root}/${named}`)
  const common = ((await io.read(`${gitDir}/commondir`)) ?? '').trim()
  const shared = common === '' ? gitDir : isAbsolute(common) ? common : normalFolder(`${gitDir}/${common}`)
  return /^ref:\s*refs\/remotes\/origin\/(.+)/.exec((await io.read(`${shared}/refs/remotes/origin/HEAD`)) ?? '')?.[1]?.trim() ?? ''
}

/**
 * Which pack a repository gets, and why, with the default branch its clone knows ('' when it cannot be told).
 * Pure over what it reads.
 * @param {PackIo} io @param {string} root
 * @returns {Promise<{ pack: Pack, source: 'profile' | 'marker' | 'none', profile: Record<string, any> | null, defaultBranch: string }>}
 */
export const choosePack = async (io, root) => {
  const profile = json(await io.read(`${root}/.ather/profile.json`))
  const packageJson = json(await io.read(`${root}/package.json`))
  const defaultBranch = await defaultBranchOf(io, root).catch(() => '')
  const named = typeof profile?.pack === 'string' ? profile.pack.toLowerCase() : ''
  if (named === 'unreal') return { pack: unreal, source: 'profile', profile, defaultBranch }
  if (named === 'core') return { pack: core, source: 'profile', profile, defaultBranch }
  const entries = await io.list(root).catch(() => [])
  const files = entries.filter(entry => entry.kind === 'file' && typeof entry.name === 'string').map(entry => entry.name)
  const web = () => makeWebPack(profile, packageJson, { files, defaultBranch })
  if (named === 'web') return { pack: web(), source: 'profile', profile, defaultBranch }
  if (entries.some(entry => entry.kind === 'file' && /\.uproject$/i.test(entry.name))) return { pack: unreal, source: 'marker', profile, defaultBranch }
  if (packageJson || entries.some(entry => entry.kind === 'file' && /^(package\.json|pyproject\.toml)$/i.test(entry.name))) return { pack: web(), source: 'marker', profile, defaultBranch }
  return { pack: core, source: 'none', profile, defaultBranch }
}

/** @type {Map<string, ReturnType<typeof choosePack>>} */
const chosen = new Map()

// Once per session and root: a profile edited mid-session takes effect in the next session.
/** @param {PackIo} io @param {string} root */
export const packFor = async (io, root) => {
  const key = `${await io.sessionId().catch(() => '')}|${root}`
  const hit = chosen.get(key)
  if (hit) return hit
  const read = choosePack(io, root)
  chosen.set(key, read)
  return read
}

// A repository that got its intents mid-session has a profile now: its pack is chosen again.
/** @param {Pick<PackIo, 'sessionId'>} io @param {string} root */
export const forgetPack = async (io, root) => void chosen.delete(`${await io.sessionId().catch(() => '')}|${root}`)

// Tests only: forget what was chosen.
export const forgetPacks = () => chosen.clear()

export { core, unreal, makeWebPack }

