// @ts-check
// Ather Automata, the web pack: Node and TypeScript web apps (piloted on Thính,
// AskTinNguyen/han-viet). Roles and their proof, the rungs (tests, lint and
// typecheck, build, ui, prod) read from tool output only (exit code plus
// pass/fail counts), the gates the repository's .ather/profile.json names,
// actions held while the person is away, known traps, and the words the
// session is asked with. Pure: no `$`.

import { MAIN, bareCommand, branchNamed, isPiped, segments, withoutHeredocs } from '../shell.mjs'

/** @typedef {import('./index.mjs').Pack} Pack */
/** @typedef {import('./index.mjs').Rung} Rung */
/** @typedef {import('./index.mjs').Gate} Gate */
/** @typedef {import('./index.mjs').Production} Production */
/** @typedef {import('./index.mjs').Found} Found */

export const RUNGS = /** @type {const} */ (['tests', 'lint', 'build', 'ui', 'prod'])
const RUNG_LABELS = { tests: 'passing tests', lint: 'a clean lint and typecheck', build: 'a build that succeeded', ui: 'a passing browser check', prod: 'a healthy production deployment' }
const PROOF_WORDS = { tests: 'tests', lint: 'lint', build: 'build', ui: 'UI', prod: 'prod' }
// A profile's proof names, folded onto the five rungs.
const ALIASES = /** @type {Record<string, string>} */ ({ tests: 'tests', test: 'tests', unit: 'tests', lint: 'lint', typecheck: 'lint', types: 'lint', tsc: 'lint', build: 'build', ui: 'ui', e2e: 'ui', a11y: 'ui', browser: 'ui', prod: 'prod', production: 'prod' })

export const ROLES = /** @type {const} */ (['engineer', 'designer', 'product'])
const ROLE_LABELS = { engineer: 'Engineer', designer: 'Designer', product: 'Product' }
const DEFAULT_AREAS = ['Product', 'Design', 'Content', 'Platform', 'Infra']

/** @param {string} text */
export const parseRole = text => {
  const words = text.toLowerCase()
  if (/design/.test(words)) return 'designer'
  if (/product|\bpm\b|manager/.test(words)) return 'product'
  if (/engineer|programmer|coder|developer|dev\b/.test(words)) return 'engineer'
  return null
}

/** @param {readonly string[]} items */
const andList = items => (items.length <= 1 ? items.join('') : `${items.slice(0, -1).join(', ')} and ${items[items.length - 1]}`)

// ---------------------------------------------------------------- commands and gates

// "npm run test", "npm t" and "npm test" are one command; spacing does not matter.
/** @param {string} command */
const normal = command =>
  bareCommand(command)
    .replace(/\s+/g, ' ')
    .replace(/^(npm|pnpm|yarn|bun)\s+(?:run\s+|run-script\s+)?(?:t|tst)$/i, '$1 test')
    .replace(/^(npm|pnpm|yarn|bun)\s+(?:run|run-script)\s+(test|start)\b/i, '$1 $2')
    .trim()

// The program a command's first word runs: the last part of its path, without ".exe" (Windows names
// have no case), and every python is one program. ".venv/bin/python" and "python3.12" are "python".
/** @param {string} word */
const programOf = word => {
  const name = word.slice(Math.max(word.lastIndexOf('/'), word.lastIndexOf('\\')) + 1) || word
  const program = /\.exe$/i.test(name) ? name.slice(0, -4).toLowerCase() : name
  return /^python(3(\.\d+)?)?$/.test(program) ? 'python' : program
}

// A command as a gate that names a bare program is compared: env prefix dropped, its first word a
// program, npm spellings folded.
/** @param {string} command */
const asTyped = command => normal(bareCommand(command).replace(/^\S+/, programOf))

// A gate's command for comparing, and whether its first word is a path. A bare program name
// ("python3", "pnpm") is that program wherever it is run from; a path ("./scripts/check.sh") is
// compared as written, so another script of the same name elsewhere does not prove it.
/** @param {string} command */
const gateCommand = command => {
  const isPath = /^\S*[\\/]/.test(bareCommand(command))
  return { isPath, command: isPath ? normal(command) : asTyped(command) }
}

// The folder a `cd` segment goes to, as written, without a trailing slash.
/** @param {string} segment */
const cdFolder = segment => /^cd\s+(.+)$/.exec(segment)?.[1]?.replace(/(?<=.)[\\/]+$/, '') ?? null

// A gate as it is compared. One written `cd <folder> && <command>` is two segments: the folder and
// the command. Any other chain (more than one `&&`, or a first segment that is not a `cd`) stays
// whole, so it never matches a command, which is read one segment at a time.
/** @param {string} gate @returns {{ folder: string | null, isPath: boolean, command: string }} */
const gateParts = gate => {
  const parts = segments(gate)
  const folder = parts.length === 2 && gate.includes('&&') ? cdFolder(parts[0] ?? '') : null
  return { folder, ...gateCommand(folder === null ? gate : parts[1] ?? '') }
}

// A mark put after each `&&` of a command before it is split: a segment that starts with it is
// joined to the one before by `&&`. `segments` itself drops the operators.
const AFTER_AND = '\u0000'

/** @param {string} segment */
const unmarked = segment => segment.replaceAll(AFTER_AND, '').trim()

// A command's segments, each one that follows an `&&` marked with AFTER_AND.
/** @param {string} command */
const markedSegments = command => segments(command.replaceAll('&&', `&&${AFTER_AND}`))

/**
 * The gates a segment runs: a gate's command is the segment or a prefix of it, and a `cd` gate also needs
 * that `cd` as the segment before, joined with `&&`: after `;`, `||` or `|` the command does not
 * depend on the `cd`, so those do not count. Among several, the longest command wins, wherever it stands;
 * gates written the same are all run.
 * @param {readonly string[]} marked the command's segments, AFTER_AND kept @param {number} at @param {readonly Gate[]} gates
 * @returns {Gate[]}
 */
const gatesRun = (marked, at, gates) => {
  const segment = unmarked(marked[at] ?? '')
  const forms = { written: normal(segment), program: asTyped(segment) }
  const before = at > 0 && (marked[at] ?? '').startsWith(AFTER_AND) ? cdFolder(unmarked(marked[at - 1] ?? '')) : null
  /** @type {Gate[]} */
  let best = []
  let longest = 0
  for (const gate of gates) {
    const { folder, isPath, command } = gateParts(gate.command)
    const typed = isPath ? forms.written : forms.program
    if (command === '' || !(typed === command || typed.startsWith(`${command} `))) continue
    if (folder !== null && folder !== before) continue
    const length = command.length + (folder === null ? 0 : `cd ${folder} && `.length)
    if (length > longest) [best, longest] = [[gate], length]
    else if (length === longest) best.push(gate)
  }
  return best
}

// The npm script a segment runs: "npm run lint" → "lint", "npm test" → "test".
/** @param {string} segment */
const scriptOf = segment => /^(?:npm|pnpm|yarn|bun)\s+(?:run\s+|run-script\s+)?([\w:.-]+)/i.exec(normal(segment))?.[1] ?? null

// What a gate's result is kept under: its id, or its command when it has none.
/** @param {Gate} gate */
const gateKey = gate => gate.id || gate.command

/** @param {string} url */
const hostOf = url => /^https?:\/\/([^/:?#\s]+)/i.exec(url)?.[1]?.toLowerCase() ?? ''

/**
 * The rungs a command tries, each with the gates it ran for that rung (none: a tool or a script that is
 * no gate): through the profile's gates first, then the scripts in package.json (one level deep), then
 * the tools it runs.
 * @param {string} command @param {Record<string, string>} scripts @param {readonly Gate[]} gates @param {Production | null} [production] @param {number} [depth]
 * @returns {Map<string, Set<string>>}
 */
const checksOfCommand = (command, scripts, gates, production = null, depth = 0) => {
  /** @type {Map<string, Set<string>>} */
  const found = new Map()
  /** @param {string} rung @param {Iterable<string>} [ran] */
  const add = (rung, ran = []) => found.set(rung, new Set([...(found.get(rung) ?? []), ...ran]))
  const marked = markedSegments(command)
  for (const [at, part] of marked.entries()) {
    const bare = bareCommand(unmarked(part))
    const ran = gatesRun(marked, at, gates)
    if (ran.length > 0) {
      for (const gate of ran) for (const proof of gate.proofs) if (ALIASES[proof] && ALIASES[proof] !== 'prod') add(ALIASES[proof], [gateKey(gate)])
      continue
    }
    const script = scriptOf(bare)
    if (script && depth < 2 && /^(npm|pnpm|yarn|bun)\b/i.test(bare) && scripts[script] !== undefined) {
      for (const [rung, inside] of checksOfCommand(scripts[script] ?? '', scripts, gates, production, depth + 1)) add(rung, inside)
      continue
    }
    if (/^node\b.*\s--test\b/i.test(bare) || /^(vitest|jest)\b/i.test(bare)) add('tests')
    else if (/^playwright\s+test\b/i.test(bare)) add('ui')
    else if (/^(tsc|vue-tsc)\b/i.test(bare) || /^(eslint|next\s+lint)\b/i.test(bare)) add('lint')
    else if (/^(next|vinext|vite|astro|nuxt|remix)\s+build\b/i.test(bare)) add('build')
    else if (isProdCheck(bare, production)) add('prod')
  }
  return found
}

/**
 * The rungs a command tries.
 * @param {string} command @param {Record<string, string>} scripts @param {readonly Gate[]} gates @param {Production | null} [production]
 * @returns {string[]}
 */
export const rungsOfCommand = (command, scripts, gates, production = null) => [...checksOfCommand(command, scripts, gates, production).keys()]

// A check of production: the deployment's status through gh or vercel, or a probe of the public URL.
/** @param {string} bare @param {Production | null} production */
const isProdCheck = (bare, production) => {
  if (/^gh\s+api\b.*(\/commits\/[^\s/]+\/(status|check-runs)\b|\/deployments\b)/i.test(bare) && !/\s(-X|--method)\s*(POST|PUT|PATCH|DELETE)\b/i.test(bare)) return true
  if (/^vercel\s+(inspect|ls|list)\b/i.test(bare)) return true
  const host = production ? hostOf(production.url) : ''
  return host !== '' && /^(curl|wget|Invoke-WebRequest|iwr|http)\b/i.test(bare) && bare.toLowerCase().includes(host)
}

// ---------------------------------------------------------------- results from tool output

// Terminal colour codes, which some tools print even into a pipe.
/** @param {string} text */
export const stripAnsi = text => text.replace(/\x1b\[[0-9;?]*[A-Za-z]/g, '')

// The command's exit: a failed tool call or "Exit code N" is a failure; a piped command's exit is the filter's.
/** @param {string} command @param {string} text @param {{ isError?: boolean }} ran @returns {'ok' | 'fail' | 'unknown'} */
export const exitOf = (command, text, ran) => {
  if (isPiped(command)) return 'unknown'
  if (ran.isError === true || /^\s*Exit code [1-9]\d*/.test(text)) return 'fail'
  return 'ok'
}

// The command's exit code is its gates' own: one command, or several joined by "&&". After a pipe, ";", "||" or a new line it is another command's.
/** @param {string} command */
const isOwnExit = command => {
  let quote = ''
  for (const char of withoutHeredocs(command).trim()) {
    if (quote !== '') quote = char === quote ? '' : quote
    else if (char === '"' || char === "'") quote = char
    else if (char === '|' || char === ';' || char === '\n') return false
  }
  return true
}

/** @param {RegExpMatchArray[]} matches @param {number} group */
const sum = (matches, group) => matches.reduce((total, match) => total + Number(match[group] ?? 0), 0)

// What a workspace runner puts before every line of a package's output: pnpm "packages/web test: ", turbo "web:test: ".
const RUNNER_PREFIX = /^[\w@./-]+[ :][\w:.#-]+: /gm

// Pass and fail counts from every runner whose summary is in the output, added up.
/** @param {string} raw */
export const testCounts = raw => {
  const text = raw.replace(RUNNER_PREFIX, '')
  const nodePass = [...text.matchAll(/^\s*[#ℹ]\s*pass\s+(\d+)\s*$/gmu)]
  const nodeFail = [...text.matchAll(/^\s*[#ℹ]\s*fail\s+(\d+)\s*$/gmu)]
  const nodeCancelled = [...text.matchAll(/^\s*[#ℹ]\s*cancelled\s+(\d+)\s*$/gmu)]
  // vitest: " Tests  1 failed | 11 passed (12)"
  const vitest = [...text.matchAll(/^\s*Tests\s+(?:(\d+) failed)?(?:\s*\|\s*)?(?:(\d+) passed)?.*\(\d+\)\s*$/gm)]
  // jest: "Tests:       1 failed, 11 passed, 12 total"
  const jest = [...text.matchAll(/^\s*Tests:\s+(?:(\d+) failed,\s*)?(?:\d+ skipped,\s*)?(?:\d+ todo,\s*)?(?:(\d+) passed,\s*)?\d+ total/gm)]
  // Playwright: "  12 passed (30.1s)", "  1 failed", "  1 flaky"
  const pwPass = [...text.matchAll(/^\s+(\d+) passed \([\d.]+m?s\)\s*$/gm)]
  const pwFail = [...text.matchAll(/^\s+(\d+) (failed|interrupted|timed out)\s*$/gm)]
  const passed = sum(nodePass, 1) + sum(vitest, 2) + sum(jest, 2) + sum(pwPass, 1)
  const failed = sum(nodeFail, 1) + sum(nodeCancelled, 1) + sum(vitest, 1) + sum(jest, 1) + sum(pwFail, 1)
  const none = /\bNo tests found\b|\bNo test files found\b|^\s*[#ℹ]\s*tests\s+0\s*$/mu.test(text)
  return { passed, failed, none, seen: nodePass.length + nodeFail.length + vitest.length + jest.length + pwPass.length + pwFail.length > 0 }
}

// ESLint and tsc errors; warnings are not failures.
/** @param {string} text */
export const lintErrors = text => {
  const eslint = [...text.matchAll(/✖\s*\d+ problems?\s*\((\d+) errors?,\s*\d+ warnings?\)/g)]
  const tsc = [...text.matchAll(/Found (\d+) errors?\b/g)]
  const tsLines = (text.match(/\berror TS\d+:/g) ?? []).length
  const typeError = /^\s*Type error:|Failed to type check/m.test(text) ? 1 : 0
  return sum(eslint, 1) + Math.max(sum(tsc, 1), tsLines) + typeError
}

const BUILD_FAILED = /Failed to compile|Build error occurred|> Build failed|\bBuild failed\b|error during build:|\[vite\]:? Rollup failed|\bERR_BUILD\b|^\s*Type error:/im
const BUILD_PASSED = /✓ Compiled successfully|^\s*Build complete\.|Compiled successfully in|✓ built in [\d.]+m?s|\bbuilt in [\d.]+m?s\b|Generating static pages.*\(\d+\/\d+\)/i

/** @param {string} text @param {Production | null} production @returns {'pass' | 'fail' | null} */
const prodResult = (text, production) => {
  const state = /"state"\s*:\s*"(success|failure|error|pending|inactive)"/i.exec(text)?.[1]?.toLowerCase()
  if (state === 'success') return 'pass'
  if (state === 'failure' || state === 'error') return 'fail'
  if (/status\s+●\s*Ready\b|●\s*Ready\b.*\bProduction\b/i.test(text)) return 'pass'
  if (/status\s+●\s*(Error|Canceled)\b/i.test(text)) return 'fail'
  const status = Number(/HTTP\/[\d.]+\s+(\d{3})/i.exec(text)?.[1] ?? /^\s*(\d{3})\s*$/m.exec(text)?.[1] ?? /StatusCode\s*:\s*(\d{3})/i.exec(text)?.[1] ?? 0)
  if (status === 0) return null
  return status === (production?.expectStatus ?? 200) ? 'pass' : status >= 400 ? 'fail' : null
}

/**
 * One rung's result from a finished command's output.
 * @param {string} rung @param {string} command @param {string} raw the output @param {{ isError?: boolean }} ran @param {Production | null} [production]
 * @param {boolean} [passesOnExit] the command ran a gate of the profile that passes on its exit code, and the exit code is that gate's own
 * @returns {Rung | null} null: nothing to record
 */
export const readToolOutput = (rung, command, raw, ran, production = null, passesOnExit = false) => {
  const text = stripAnsi(raw)
  const exit = exitOf(command, text, ran)
  if (rung === 'tests' || rung === 'ui') {
    const counts = testCounts(text)
    if (counts.failed > 0) return { state: 'fail', detail: `${counts.failed} failed${counts.passed > 0 ? `, ${counts.passed} passed` : ''}` }
    if (exit === 'fail') return { state: 'fail', detail: 'exited non-zero' }
    if (counts.none) return { state: 'fail', detail: 'no tests ran' }
    if (counts.passed > 0) return { state: 'pass', detail: `${counts.passed} passed, 0 failed` }
    if (passesOnExit && exit === 'ok') return { state: 'pass', detail: 'exit 0, no test counts' }
    // Every run replaces the last result: a run whose outcome cannot be read is no evidence.
    return { state: 'none', detail: 'no test counts read' }
  }
  if (rung === 'lint') {
    const errors = lintErrors(text)
    if (errors > 0) return { state: 'fail', detail: `${errors} error${errors === 1 ? '' : 's'}` }
    if (exit === 'fail') return { state: 'fail', detail: 'exited non-zero' }
    return exit === 'ok' ? { state: 'pass', detail: 'exit 0, no errors' } : { state: 'none', detail: 'piped: exit code not read' }
  }
  if (rung === 'build') {
    if (BUILD_FAILED.test(text) || exit === 'fail') return { state: 'fail', detail: exit === 'fail' ? 'exited non-zero' : 'the build reported a failure' }
    if (exit === 'ok' || BUILD_PASSED.test(text)) return { state: 'pass', detail: exit === 'ok' ? 'exit 0' : 'build reported success' }
    return { state: 'none', detail: 'piped: exit code not read' }
  }
  if (rung === 'prod') {
    const result = prodResult(text, production)
    return result === null ? null : { state: result, detail: result === 'pass' ? 'production healthy' : 'production check failed' }
  }
  return null
}

// ---------------------------------------------------------------- held while away

const HELD_LABELS = { 'deploy-prod': 'Production deploys', migrate: 'Migrations against a non-local database', 'env-secret': 'Environment and secret changes', publish: 'Package publishes', 'infra-apply': 'Infrastructure applies' }
const HELD_NOUNS = { 'deploy-prod': 'a production deploy', migrate: 'a migration against a non-local database', 'env-secret': 'an environment or secret change', publish: 'a package publish', 'infra-apply': 'an infrastructure apply' }
export const WEB_HELD = /** @type {const} */ (['deploy-prod', 'migrate', 'env-secret', 'publish', 'infra-apply'])

const WRITE = /\s(-X|--method)\s*(POST|PUT|PATCH|DELETE)\b/i
// A database URL given inline that points at this machine.
const LOCAL_DB = /\b(DATABASE_URL|DB_URL|POSTGRES_URL|MYSQL_URL|TURSO_DATABASE_URL)=\S*(localhost|127\.0\.0\.1|\[::1\]|file:|:memory:)/i

/** @param {string} segment the segment as typed (env assignments kept) @returns {string | null} */
const heldKindOf = segment => {
  const bare = bareCommand(segment)
  if (/^vercel\b(?!\s+(env|inspect|ls|list|logs|whoami|login|link|pull)\b).*\s--prod(uction)?\b/i.test(bare) || /^vercel\s+(promote|rollback|alias\s+set)\b/i.test(bare)) return 'deploy-prod'
  if (/^wrangler\s+(deploy|publish)\b/i.test(bare) && !/--dry-run\b/i.test(bare)) return 'deploy-prod'
  if (/^wrangler\s+pages\s+deploy\b/i.test(bare) && !/--branch[=\s]+(?!main\b|master\b)\S+/i.test(bare)) return 'deploy-prod'
  if (/^(netlify\s+deploy\b.*--prod|firebase\s+deploy\b|fly(ctl)?\s+deploy\b)/i.test(bare)) return 'deploy-prod'
  if (/^gh\s+api\b/i.test(bare) && WRITE.test(bare) && /\/deployments\b/i.test(bare) && /production/i.test(bare)) return 'deploy-prod'
  const isMigration =
    /^drizzle-kit\s+(migrate|push)\b/i.test(bare) ||
    /^prisma\s+(migrate\s+(deploy|reset)|db\s+push)\b/i.test(bare) ||
    /^knex\s+migrate:(latest|up|down|rollback)\b/i.test(bare) ||
    /^sequelize(-cli)?\s+db:migrate\b/i.test(bare) ||
    /^typeorm\s+migration:(run|revert)\b/i.test(bare) ||
    /^supabase\s+db\s+(push|reset)\b/i.test(bare) ||
    (/^wrangler\s+d1\s+(migrations\s+apply|execute)\b/i.test(bare) && /--remote\b/i.test(bare))
  if (isMigration && !/--local\b/i.test(bare) && !LOCAL_DB.test(segment)) return 'migrate'
  if (/^vercel\s+env\s+(add|rm|remove|update)\b/i.test(bare) || /^wrangler\s+(pages\s+)?secret\s+(put|delete|bulk)\b/i.test(bare) || /^gh\s+(secret|variable)\s+(set|delete|remove)\b/i.test(bare)) return 'env-secret'
  if (/^gh\s+api\b/i.test(bare) && WRITE.test(bare) && /\/(actions|dependabot|codespaces|environments\/[^/\s]+)\/(secrets|variables)\b/i.test(bare)) return 'env-secret'
  if (/^(npm|pnpm|yarn|bun)\s+(npm\s+)?publish\b/i.test(bare) && !/--dry-run\b/i.test(bare)) return 'publish'
  if (/^(terraform|tofu)\s+(apply|destroy)\b/i.test(bare) || /^pulumi\s+(up|destroy)\b/i.test(bare)) return 'infra-apply'
  // A merge spelled through the GraphQL API is still a merge.
  if (/^gh\s+api\s+graphql\b.*\bmergePullRequest\b/i.test(bare) || /^gh\s+api\b.*\/merges\b/i.test(bare) && WRITE.test(bare)) return 'merge'
  return null
}

/**
 * A segment the window holds beyond merges and pushes to main; `npm run <script>` is read through package.json.
 * @param {string} segment @param {readonly string[]} held @param {import('./index.mjs').HeldContext} context @param {number} [depth]
 * @returns {string | null}
 */
export const heldSegment = (segment, held, context, depth = 0) => {
  const kind = heldKindOf(segment)
  if (kind && held.includes(kind)) return kind
  const script = scriptOf(bareCommand(segment))
  const body = script ? context.scripts?.[script] : undefined
  if (body !== undefined && depth < 2) {
    for (const part of segments(body)) {
      const inner = heldSegment(part, held, context, depth + 1)
      if (inner) return inner
    }
  }
  return null
}

// ---------------------------------------------------------------- known traps

export const WEB_TRAPS = [
  { id: 'web-port-in-use', pattern: /\bEADDRINUSE\b|address already in use|Port \d+ is (already )?in use/i, title: 'A dev server port is already in use (EADDRINUSE)', fix: 'Another server holds the port. Give each worktree its own port from the profile (base + 10 per worktree), or stop the old server: Get-NetTCPConnection -LocalPort <port> on Windows, lsof -i :<port> elsewhere.' },
  { id: 'web-posix-env', pattern: /'[A-Z][A-Z0-9]*_[A-Z0-9_]*(=[^']*)?' is not recognized as an internal or external command|The term '[A-Z][A-Z0-9]*_[A-Z0-9_]*=\S*' is not recognized/, title: 'POSIX env syntax in an npm script on Windows', fix: 'npm runs scripts with cmd.exe on Windows, which does not take FOO=bar cmd. Move the variable into a small Node launcher (process.env) or cross-env; for a one-off run set npm_config_script_shell to Git Bash.' },
  { id: 'web-hydration', pattern: /Hydration failed|hydration mismatch|Text content does not match server-rendered HTML|did not match\. Server:|error while hydrating/i, title: 'Hydration mismatch between server and client HTML', fix: 'The server and the browser rendered different HTML: move Date.now(), Math.random(), locale formatting and window or localStorage reads into useEffect, and use suppressHydrationWarning only where the difference is intended.' },
  { id: 'web-stale-cache', pattern: /Cannot find module '\.\/(chunks|vendor-chunks)\/|ENOENT: no such file or directory, open '[^']*\.next[\\/]|Outdated Optimize Dep|node_modules[\\/]\.vite[\\/]deps|Failed to fetch dynamically imported module/i, title: 'Stale .next or Vite cache', fix: 'Stop the dev server, delete .next (Next) or node_modules/.vite (Vite, vinext), then start again. Never commit either folder.' },
  { id: 'web-lockfile-drift', pattern: /can only install packages when your package\.json and package-lock\.json|ERR_PNPM_OUTDATED_LOCKFILE|Your lockfile needs to be updated|Found multiple lockfiles|multiple lockfiles/i, title: 'Lockfile out of step with package.json, or two package managers', fix: 'Use the package manager the profile names: run its install once, commit the lockfile with the package.json change, and delete any other lockfile (yarn.lock, pnpm-lock.yaml, package-lock.json).' },
  { id: 'web-node-version', pattern: /\bEBADENGINE\b|Unsupported engine|The engine "node" is incompatible|requires Node(\.js)? (version )?[>=^~]/i, title: 'Node version does not match engines or .nvmrc', fix: 'Switch to the Node version package.json engines or .nvmrc asks for (nvm, fnm or volta), then reinstall dependencies.' },
  { id: 'web-next-public-env', pattern: /NEXT_PUBLIC_[A-Z0-9_]+[^\n]{0,40}\b(is not defined|is undefined|is missing|not set|is required)|(Missing|Invalid) environment variables?[^\n]{0,80}NEXT_PUBLIC_/i, title: 'A NEXT_PUBLIC_* variable is missing', fix: 'NEXT_PUBLIC_* values are inlined at build time: add it to .env.local for local runs and to the Vercel project environment for previews and production, then rebuild. Never commit the value.' },
  { id: 'web-playwright-browsers', pattern: /Executable doesn't exist at [^\n]*ms-playwright|Please run the following command to download new browsers|Looks like Playwright Test or Playwright was just installed or updated/i, title: 'Playwright browsers are not installed', fix: 'Install once with npx playwright install chromium, or point PLAYWRIGHT_BROWSERS_PATH at an existing install. Never add a postinstall that downloads browsers: it would run on Vercel too.' },
  { id: 'web-next-lock', pattern: /Unable to acquire lock at [^\n]*\.next[\\/]lock|Another next build process is already running/i, title: 'Another next build holds .next', fix: 'Another next build or next dev runs in this checkout: wait for it, or build in its own worktree.' },
]

// ---------------------------------------------------------------- Create

// Skills Claude Code has everywhere: offered whether or not the repository has a skills folder.
const CREATE_GROUPS = [
  { group: 'Build and look', items: [{ name: 'frontend-design', verb: 'Design or restyle a page or component', isGlobal: true }] },
  { group: 'See it running', items: [{ name: 'run', verb: 'Run the app and see the change working', isGlobal: true }] },
  { group: 'Review before it ships', items: [
    { name: 'code-review', verb: 'Review the current change for bugs', isGlobal: true },
    { name: 'security-review', verb: 'Review the change for security issues', isGlobal: true },
    { name: 'simplify', verb: 'Clean up the changed code', isGlobal: true },
  ] },
]
const CREATE_ORDER = {
  engineer: ['Build and look', 'Review before it ships', 'See it running'],
  designer: ['Build and look', 'See it running', 'Review before it ships'],
  product: ['See it running', 'Build and look', 'Review before it ships'],
}

// ---------------------------------------------------------------- the profile

/**
 * The profile's gates: [{ command, proofs: [...] }] (han-viet), or { name: { command, proofs | proof } }.
 * `passOn` says how a gate's tests and ui proofs pass: "exit" or "counts"; anything else is no field.
 * @param {any} profile @returns {Gate[]}
 */
export const gatesOf = profile => {
  const raw = profile?.gates
  const list = Array.isArray(raw) ? raw : raw && typeof raw === 'object' ? Object.entries(raw).map(([id, gate]) => ({ id, ...(typeof gate === 'string' ? { command: gate } : gate) })) : []
  return list
    .filter(gate => gate && typeof gate.command === 'string' && gate.command.trim() !== '')
    .map(gate => {
      const proofs = [gate.proofs, gate.proof, gate.kind, gate.rungs].flat().filter(one => typeof one === 'string').map(one => ALIASES[one.toLowerCase()] ?? '').filter(Boolean)
      const passOn = gate.passOn === 'exit' || gate.passOn === 'counts' ? { passOn: /** @type {'exit' | 'counts'} */ (gate.passOn) } : {}
      return { id: typeof gate.id === 'string' ? gate.id : '', command: gate.command.trim(), proofs: [...new Set(proofs)], proves: typeof gate.proves === 'string' ? gate.proves : '', ...passOn }
    })
}

/** @param {any} profile @returns {Production | null} */
export const productionOf = profile => {
  const raw = profile?.production
  if (!raw || typeof raw !== 'object') return null
  const url = typeof raw.probe?.url === 'string' ? raw.probe.url : typeof raw.url === 'string' ? raw.url : ''
  return { host: String(raw.host ?? ''), branch: String(raw.branch ?? 'main'), deployment: typeof raw.deployment === 'string' ? raw.deployment : '', url, expectStatus: Number(raw.probe?.expectStatus ?? raw.expectStatus ?? 200) || 200 }
}

// "pnpm@9.12.0+sha512…" and "pnpm" are pnpm; anything else is no runner.
/** @param {unknown} value */
const runnerNamed = value => (typeof value === 'string' ? /^(npm|pnpm|yarn|bun)(?:@|$)/.exec(value.trim())?.[1] ?? null : null)

const LOCKFILES = /** @type {const} */ ([['pnpm-lock.yaml', 'pnpm'], ['yarn.lock', 'yarn'], ['bun.lock', 'bun'], ['bun.lockb', 'bun']])

/**
 * The package manager a repository's scripts are run with: the profile's word, then package.json's, then a lockfile at the root, then npm.
 * @param {any} profile @param {any} packageJson @param {Found} found
 */
const runnerOf = (profile, packageJson, found) => {
  const files = Array.isArray(found?.files) ? found.files : []
  return runnerNamed(profile?.packageManager) ?? runnerNamed(packageJson?.packageManager) ?? LOCKFILES.find(([file]) => files.includes(file))?.[1] ?? 'npm'
}

/**
 * The branch pull requests go into, when it is not main or master: the profile's word, then the default branch the clone knows.
 * @param {any} profile @param {Found} found
 */
const baseBranchOf = (profile, found) => {
  const name = branchNamed(profile?.baseBranch) || branchNamed(found?.defaultBranch)
  return MAIN.test(name) ? '' : name
}

// The scripts that stand in for each rung's gates, in the order they are named.
const RUNG_SCRIPTS = /** @type {Record<string, string[]>} */ ({ tests: ['test'], lint: ['lint', 'typecheck'], build: ['build'] })

// `bun test` is Bun's own test runner, not the test script: bun keeps the `run`.
/** @param {string} runner @param {string} script */
const scriptCommand = (runner, script) => (runner === 'npm' ? (script === 'test' ? 'npm test' : `npm run ${script}`) : runner === 'bun' ? `bun run ${script}` : `${runner} ${script}`)

/**
 * The web pack for one repository, from its profile (or none), its package.json and what else was read at its root.
 * @param {any} profile @param {any} packageJson @param {Found} [found] @returns {Pack}
 */
export const makeWebPack = (profile, packageJson, found = {}) => {
  const gates = gatesOf(profile)
  const production = productionOf(profile)
  /** @type {Record<string, string>} */
  const scripts = packageJson?.scripts && typeof packageJson.scripts === 'object' ? Object.fromEntries(Object.entries(packageJson.scripts).filter(([, body]) => typeof body === 'string')) : {}
  const declared = new Set(gates.flatMap(gate => gate.proofs))
  // Without a profile, the usual scripts stand in for gates.
  if (gates.length === 0) {
    for (const [rung, names] of Object.entries(RUNG_SCRIPTS)) if (names.some(name => scripts[name] !== undefined)) declared.add(rung)
  }
  if (production) declared.add('prod')
  const mergePolicy = String(profile?.mergePolicy ?? profile?.merge ?? '').toLowerCase() === 'with-proof' ? 'with-proof' : 'hold'
  const merging = [...declared].filter(rung => rung !== 'prod')
  const required = Array.isArray(profile?.required) ? profile.required.map((/** @type {string} */ one) => ALIASES[String(one).toLowerCase()] ?? '').filter(Boolean) : merging
  /** @type {Record<string, string[]>} */
  const wants = { engineer: ['tests', 'lint', 'build'], designer: ['ui'], product: ['build', 'ui'] }
  /** @param {string} role */
  const requiredRungs = role => {
    const want = (wants[role] ?? wants.engineer ?? []).filter(rung => declared.has(rung))
    return want.length > 0 ? want : declared.has('build') ? ['build'] : ['tests', 'build']
  }
  // The gates that declare each rung, by what their results are kept under. Production is checked after the merge, by no gate.
  /** @type {Record<string, string[]>} */
  const rungGates = {}
  for (const gate of gates) for (const rung of gate.proofs) if (rung !== 'prod') rungGates[rung] = [...new Set([...(rungGates[rung] ?? []), gateKey(gate)])]
  const runner = runnerOf(profile, packageJson, found)
  // The commands that prove a rung: every gate of the profile that declares it, else its scripts, run with the repository's package manager.
  // Beside a profile's gates, a rung that no gate declares names its first script alone.
  /** @param {string} rung */
  const gatesFor = rung => {
    const named = gates.filter(gate => gate.proofs.includes(rung)).map(gate => gate.command)
    if (named.length > 0) return named
    return (RUNG_SCRIPTS[rung] ?? []).slice(0, gates.length > 0 ? 1 : undefined).filter(name => scripts[name]).map(name => scriptCommand(runner, name))
  }
  /** @param {readonly string[]} rungs */
  const commandsFor = rungs => [...new Set(rungs.flatMap(gatesFor))].map(command => `\`${command}\``)
  const prodCheck = production ? `the production check (${production.host ? `${production.host[0]?.toUpperCase()}${production.host.slice(1)} ` : ''}deployment for the merge commit READY${production.url ? `, then ${production.url} answers ${production.expectStatus}` : ''})` : ''
  const mergeGates = andList(commandsFor(required))
  const port = Number(profile?.devPorts?.base ?? profile?.devPortBase ?? 0)

  /** @param {string} command @param {string} text @param {{ isError?: boolean, deny?: string }} ran */
  const readShell = (command, text, ran) => {
    /** @type {import('./index.mjs').ShellReading} */
    const out = { rungs: [], context: [], toasts: [], bumps: [] }
    // A call that was denied never ran.
    if (ran.deny !== undefined) return out
    const checks = checksOfCommand(command, scripts, gates, production)
    const rungs = [...checks.keys()]
    // A gate passes on its exit code when the command runs it itself, unless the profile says it passes on test counts.
    // A gate found inside a script is read on counts.
    const marked = markedSegments(command)
    const direct = marked.flatMap((_, at) => gatesRun(marked, at, gates).filter(gate => gate.passOn !== 'counts'))
    const onExit = new Set(direct.map(gateKey))
    const isOwn = isOwnExit(command)
    let isHidden = false
    for (const rung of rungs) {
      const all = rungGates[rung]
      const keys = [...(checks.get(rung) ?? [])]
      const exits = keys.filter(key => onExit.has(key))
      // The command has one output and one exit code: every gate in it gets this reading, each kind of gate under its own way of passing.
      const kinds = (rung === 'tests' || rung === 'ui') && exits.length > 0 && exits.length < keys.length ? [exits, keys.filter(key => !onExit.has(key))] : [keys]
      for (const kind of kinds) {
        const passesOnExit = kind.some(key => onExit.has(key))
        const value = readToolOutput(rung, command, text, ran, production, passesOnExit && isOwn)
        if (passesOnExit && !isOwn && value?.state === 'none') isHidden = true
        if (value) out.rungs.push(all ? { rung, value, gates: { ran: kind, all } } : { rung, value })
      }
    }
    if (rungs.length > 0 && isPiped(command) && out.rungs.some(one => one.value.state === 'none')) {
      out.context.push('Ather Automata: this check was piped through a filter, so its exit code is the filter\'s. Read the pass and fail counts (or run it unpiped) before claiming it passed.')
    } else if (isHidden) {
      out.context.push('Ather Automata: this gate passes on its exit code, and a pipe, ";" or "||" in the command hides it. Run the gate by itself, or after "&&" only, before claiming it passed.')
    }
    return out
  }

  const areas = Array.isArray(profile?.areas) && profile.areas.every((/** @type {unknown} */ one) => typeof one === 'string') ? profile.areas : DEFAULT_AREAS
  const flags = 'keep behaviour changes behind a flag that defaults to the current behaviour'
  const withProof = mergePolicy === 'with-proof'
  const baseBranch = baseBranchOf(profile, found)
  const into = baseBranch ? ` into ${baseBranch}` : ''
  return {
    id: 'web',
    roles: ROLES,
    roleLabels: ROLE_LABELS,
    roleDescriptions: {
      engineer: `${andList(commandsFor(requiredRungs('engineer'))) || 'Tests and a build'} passing.`,
      designer: `${andList(commandsFor(requiredRungs('designer'))) || 'The browser check'} passing.`,
      product: `${andList(commandsFor(requiredRungs('product'))) || 'A build'} passing${production ? ', then production' : ''}.`,
    },
    roleWords: 'engineer, designer or product',
    roleHelp: 'Which role? /ather role engineer, /ather role designer or /ather role product.',
    roleFallback: 'Tour skipped. Say your role any time with /ather role engineer, designer or product.',
    roleKey: 'web:',
    parseRole,
    owners: 'the repository owner',
    areas,
    normalizeArea: text => areas.find((/** @type {string} */ area) => area.toLowerCase() === text.trim().toLowerCase()) ?? 'Unsorted',
    rungLabels: RUNG_LABELS,
    proofWords: PROOF_WORDS,
    emptyEvidence: () => Object.fromEntries(RUNGS.map(rung => [rung, { state: 'none', detail: '' }])),
    requiredRungs,
    isProven: (evidence, role) => requiredRungs(role || 'engineer').every(rung => evidence[rung]?.state === 'pass'),
    anyProofText: andList(requiredRungs('engineer').map(rung => RUNG_LABELS[/** @type {keyof typeof RUNG_LABELS} */ (rung)] ?? rung)),
    localDir: '.ather/local',
    debriefPath: slug => `docs/intent/${slug}/debrief.md`,
    lockFile: null,
    parseLock: () => ({ state: 'unknown', holder: '', until: '', isStale: false, raw: '', session: '' }),
    lockRoles: [],
    ownCheck: null,
    traps: WEB_TRAPS,
    held: {
      labels: baseBranch ? { ...HELD_LABELS, 'push-main': `Pushes to ${baseBranch} and main` } : HELD_LABELS,
      nouns: baseBranch ? { ...HELD_NOUNS, 'push-main': `a push to ${baseBranch} or main` } : HELD_NOUNS,
      kinds: WEB_HELD,
      defaults: ['merge', 'push-main', ...WEB_HELD],
    },
    heldSegment,
    mergePolicy,
    baseBranch,
    mergeRungs: required,
    rungGates,
    isAssetSave: () => false,
    readShell,
    mcpKind: () => null,
    binaryAssets: null,
    briefPaths: /[A-Za-z]:[\\/]|\b(app|src|pages|components|lib|tests?|scripts|public|docs|data|schemas|worker)\/|\.(js|mjs|cjs|ts|tsx|jsx|css|json|md|html|sql)\b/,
    skillGroups: [],
    createGroups: CREATE_GROUPS,
    createOrder: CREATE_ORDER,
    createTitle: 'Make or check it',
    createMeta: () => `The session asks what you want first${port ? `, works in its own worktree on a dev port from ${port}` : ''} and proves it with ${andList(commandsFor(requiredRungs('engineer'))) || 'the repository checks'}.`,
    createPrompt: (verb, name) =>
      /review|simplify/.test(name)
        ? `Run the ${name} skill on the current work: read it, tell me in two lines what it will do here, then follow it, and report what it found before changing anything.`
        : `I want to ${verb.charAt(0).toLowerCase()}${verb.slice(1)}. Use the ${name} skill. First ask me what I want, one question at a time and at most three. Then record it as an intent with the intent skill (.agents/skills/intent/SKILL.md), do it in its own worktree, prove it with ${andList(commandsFor(requiredRungs('designer').concat(requiredRungs('engineer')))) || 'the repository checks'}, and show me the result.`,
    prompts: {
      brief: (role, slug) =>
        `Dispatch a background Opus worker for intent ${slug} using .agents/skills/intent/assets/worker-brief.md: exact paths, the acceptance checks it must prove with ${andList(commandsFor(requiredRungs(role))) || 'the repository checks'}, its own worktree (git worktree add)${port ? ` and dev port (from ${port}, 10 per worktree)` : ''}, no commits in the main checkout.`,
      prove: (role, slug) =>
        `Prove intent ${slug}: run ${andList(commandsFor(requiredRungs(role))) || 'the build and the tests'} and report each command's own exit code and its pass and fail counts${requiredRungs(role).includes('ui') ? ', and the screens the browser check covered' : ''}. Ather reads the result from tool output.`,
      ship: (role, slug) =>
        role === 'product'
          ? `Summarise intent ${slug} for landing: what changed, the gate that proved each checklist item, and what is still owed${prodCheck ? `; after it merges, run ${prodCheck}` : ''}.`
          : withProof
            ? `Land intent ${slug}: open the PR from its branch${into}, confirm ${mergeGates || 'every gate'} passed on its head in this session, then merge it (merge policy with-proof)${prodCheck ? ` and run ${prodCheck}` : ''}. If any gate has not passed, stop and tell me.`
            : `Prepare intent ${slug} for landing: open the PR from its branch${into} with the evidence for each checklist item, then wait for my go before merging.`,
      shipHint: role => (role === 'product' ? 'Summarises the work and checks production once it lands.' : withProof ? `Merges once ${mergeGates || 'every gate'} passed; then checks production.` : 'A clean PR; nothing merges without your go.'),
      briefHint: 'A background agent does the work in its own worktree, proved with the repository gates.',
      tour: 'Give me the Ather tour for this repository: read AGENTS.md, .ather/profile.json and .agents/skills/intent/SKILL.md, then explain in six short steps how a feature runs here as an intent (Plan, Build, Prove with the gates the profile names, Ship), ending with my first intent started.',
      tourToast: 'Ather: new here? Type /ather tour for a six-step tour of how this repository works with Claude Code.',
      ask: question => `I asked Ather: "${question}" Answer briefly in plain words. Ather is a Claude Code mod: /ather shows what needs me and the next step, /ather tour walks a newcomer through the workflow, /away hands over while I am away. The repository's gates are in .ather/profile.json. If the question is about my work instead, answer from this checkout.`,
    },
    mandate: {
      flags,
      allowed: withProof ? `push branches, open PRs, merge PRs to ${baseBranch || 'main'} once ${mergeGates || 'every gate'} passed` : `push branches, open draft PRs, open PRs to ${baseBranch || 'main'}`,
      merge: withProof ? 'merge only when every gate the profile requires has passed in this session' : 'never merge',
      away: withProof ? 'The session may push branches, open PRs and merge with every gate passed; production deploys, migrations and secrets wait for you.' : 'The session may push branches and open PRs; nothing merges until you are back.',
      pane: 'The session keeps working; production deploys, migrations and secret changes wait for your review.',
    },
    statusWhat: 'this web repository session',
    notHere: 'Ather Automata works in repositories with intents (a docs/intent folder); none here.',
    gates,
    production,
    scripts,
  }
}

files.hooks/squad.mjs:
// @ts-check
// Ather Automata: the worker squad. What kind of worker each background agent is (fixed when it
// is dispatched), what it is doing now (from its latest tool call), and how it is drawn: a ring
// for its state, a body and colour for its kind, the prop it holds. Pure: no `$`.

import { isAutomationCommand, isBuildCommand, mcpKind } from './guards.mjs'

/** @typedef {'editor' | 'builder' | 'tester' | 'scout' | 'reviewer' | 'general'} Kind */
/** @typedef {'reading' | 'editing' | 'building' | 'testing' | 'editor' | 'reviewing' | 'profiling' | 'asking' | 'idle'} Prop `asking`: a question to the person in flight; `idle`: computed silence */
/** @typedef {'running' | 'done' | 'failed' | 'waiting'} WorkerState */
/** @typedef {'seen' | 'adopted' | 'unknown'} Origin how much Ather knows of a worker: saw it dispatched, found it running later, or neither */

// One body and one colour per kind: colour reads from across the room, the shape still reads
// for colour-blind teammates and at small sizes.
export const KINDS = /** @type {const} */ ({
  editor: { word: 'Editor', body: 'pill', fill: '#f08a3c', light: true },
  builder: { word: 'Builder', body: 'square', fill: '#2f8cf0', light: false },
  tester: { word: 'Tester', body: 'starfish', fill: '#2fbfa8', light: true },
  scout: { word: 'Scout', body: 'cloud', fill: '#c9b3ee', light: true },
  reviewer: { word: 'Reviewer', body: 'moon', fill: '#f2d27a', light: true },
  general: { word: 'General', body: 'blob', fill: '#ec5fa4', light: false },
})

export const STATE_COLOURS = /** @type {const} */ ({ running: '#ddff00', done: '#3ccf7a', failed: '#ff5a45', waiting: '#6b6e67' })
export const STATE_GLYPHS = /** @type {const} */ ({ running: '●', done: '✓', failed: '✗', waiting: '○' })

export const PROP_WORDS = /** @type {const} */ ({
  reading: 'reading', editing: 'editing files', building: 'building', testing: 'testing', editor: 'in the Editor', reviewing: 'reviewing', profiling: 'profiling', asking: 'asking you', idle: 'quiet',
})
const TRAIL_WORDS = /** @type {const} */ ({ reading: 'read', editing: 'edit', building: 'build', testing: 'test', editor: 'Editor', reviewing: 'review', profiling: 'profile', asking: 'ask', idle: 'wait' })

// ---------------------------------------------------------------- what kind, what now

// The kind, from the dispatch: the agent type first, then its short description, then the brief.
// The description says what the worker is for: "Thermo round 1 fixes" fixes what a review found,
// a builder, though its brief quotes the review throughout.
/** @param {{ subagentType: string, prompt: string, description?: string }} spawn @returns {Kind} */
export const classifyWorker = ({ subagentType, prompt, description = '' }) => {
  if (/^(explore|plan)$/i.test(subagentType)) return 'scout'
  return kindOf(description) ?? kindOf(prompt) ?? 'general'
}

// A worker known only by its type and description (no brief seen).
/** @param {string} type @param {string} description */
export const kindOfAgent = (type, description) => classifyWorker({ subagentType: type, prompt: '', description })

/** @param {string} text @returns {Kind | null} */
const kindOf = text => {
  if (/\b(review|reviewer|verify|verification|critique|audit|thermo-nuclear|fresh[- ]eyes|adversarial)\b/i.test(text)) return 'reviewer'
  if (/EDITOR_OWNER|Editor owner lock|only Editor MCP user|\bunreal-mcp\b|Editor MCP/i.test(text)) return 'editor'
  if (/\b(test|tests|testing|PIE|simulation|TALab|automation|prove|proof)\b/i.test(text)) return 'tester'
  if (/\b(build|implement|edit|write|fix|fixes|refactor|code|port|migrate)\b/i.test(text)) return 'builder'
  return null
}

// What a worker is doing, from one of its tool calls; null keeps what it was doing.
/** @param {string} tool @param {Record<string, unknown>} input @returns {Prop | null} */
export const propForTool = (tool, input) => {
  if (/^(Read|Grep|Glob|LS|WebFetch|WebSearch|NotebookRead)$/.test(tool)) return 'reading'
  if (/^(Edit|Write|MultiEdit|NotebookEdit)$/.test(tool)) return 'editing'
  // A question waits on the person. A message sent is not waiting on anything: SendMessage does not wait for a reply.
  if (tool === 'AskUserQuestion') return 'asking'
  if (tool === 'Skill') return /review|thermo/i.test(String(input.skill ?? '')) ? 'reviewing' : null
  if (tool === 'Bash' || tool === 'PowerShell') {
    const command = String(input.command ?? '')
    if (isAutomationCommand(command)) return 'testing'
    if (isBuildCommand(command)) return 'building'
    if (/insights|stat (unit|fps)|profil|memreport|Bench\.Combo/i.test(command)) return 'profiling'
    if (/\b(grep|rg|findstr|Select-String|cat|type|ls|dir|git (log|show|diff|status))\b/i.test(command)) return 'reading'
    return null
  }
  if (tool.startsWith('mcp__')) {
    const kind = mcpKind(`${tool} ${JSON.stringify(input).slice(0, 4000)}`)
    if (kind === 'pie') return 'testing'
    return /unreal|editor/i.test(tool) ? 'editor' : 'reading'
  }
  return null
}

// "read → edit → build → test": the distinct steps a worker went through, in order.
/** @param {readonly Prop[]} trail */
export const trailWords = trail => trail.map(prop => TRAIL_WORDS[prop]).join(' → ')

// Running, or queued to run (Claude Code's pending): not finished.
/** @param {WorkerState} state */
export const isLive = state => state === 'running' || state === 'waiting'

/** @param {string} status @returns {WorkerState} */
export const workerState = status => (status === 'running' ? 'running' : status === 'completed' ? 'done' : /fail|kill|error|cancel/i.test(status) ? 'failed' : 'waiting')

/** @param {string} model */
export const modelWord = model => (/opus/i.test(model) ? 'Opus' : /sonnet/i.test(model) ? 'Sonnet' : /haiku/i.test(model) ? 'Haiku' : /fable/i.test(model) ? 'Fable' : model)

// "6:40", or "1:02h" past an hour.
/** @param {number} ms */
export const durationText = ms => {
  const seconds = Math.max(0, Math.round(ms / 1000))
  return seconds >= 3600 ? `${Math.floor(seconds / 3600)}:${String(Math.floor((seconds % 3600) / 60)).padStart(2, '0')}h` : `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`
}

/**
 * What a worker row says, from what is known of the worker. `origin`: 'seen' (Ather saw it
 * dispatched), 'adopted' (found running later; start from Claude Code's record), 'unknown' (no record).
 * `elapsed` null: its time is not known. `via`: the worker that started it when that one is not drawn
 * above it ("Thermo round 1 fixes", "Thermo round 1 fixes (finished)"), or ''.
 * @param {{ state: WorkerState, prop: Prop | null, origin: Origin, elapsed: number | null, tools: number, via: string }} one
 * @returns {{ doing: string, line: string }}
 */
export const crewWords = one => {
  const isRunning = isLive(one.state)
  const isFresh = one.origin === 'seen' && one.elapsed !== null && one.elapsed < 60000
  // Claude Code's pending status (not running yet) reads "queued": "waiting" is kept for a worker waiting on something (⏳).
  const isQueued = one.state === 'waiting'
  const doing = !isRunning ? (one.state === 'done' ? 'finished' : 'stopped') : isQueued ? 'queued' : one.prop ? PROP_WORDS[one.prop] : isFresh ? 'starting' : 'working'
  const liveWord = isQueued ? 'queued' : 'running'
  const time = one.elapsed === null ? (isRunning ? `${liveWord} · start unknown` : '') : `${isRunning ? liveWord : one.state === 'done' ? 'took' : 'stopped at'} ${durationText(one.elapsed)}`
  // Counted only for a worker Ather saw start: one found later shows no count rather than too few.
  const tools = one.origin === 'seen' ? `${one.tools} tool call${one.tools === 1 ? '' : 's'}` : ''
  return { doing, line: [time, tools, one.via ? `started by ${one.via}` : ''].filter(Boolean).join(' · ') }
}

// ---------------------------------------------------------------- drawing

const BODIES = {
  blob: { shape: (/** @type {string} */ f) => `<ellipse cx="50" cy="88" rx="36" ry="46" fill="${f}"/>`, eyes: [[40, 64], [59, 64]] },
  square: { shape: (/** @type {string} */ f) => `<rect x="19" y="44" width="62" height="74" rx="17" fill="${f}" transform="rotate(-8 50 76)"/>`, eyes: [[39, 64], [58, 61]] },
  pill: { shape: (/** @type {string} */ f) => `<rect x="28" y="30" width="44" height="96" rx="22" fill="${f}"/>`, eyes: [[42, 52], [58, 52]], tall: true },
  starfish: { shape: (/** @type {string} */ f) => `<path d="M50 50 L57.6 69.5 L78.5 70.7 L62.4 84 L67.6 104.3 L50 93 L32.4 104.3 L37.6 84 L21.5 70.7 L42.4 69.5 Z" fill="${f}" stroke="${f}" stroke-width="10" stroke-linejoin="round"/>`, eyes: [[44.5, 77], [55.5, 77]] },
  cloud: { shape: (/** @type {string} */ f) => `<g fill="${f}"><circle cx="32" cy="72" r="18"/><circle cx="50" cy="60" r="21"/><circle cx="68" cy="72" r="18"/><rect x="18" y="72" width="64" height="44" rx="14"/></g>`, eyes: [[42, 74], [59, 74]] },
  moon: { shape: (/** @type {string} */ f) => `<defs><mask id="moon"><rect width="100" height="130" fill="#fff"/><circle cx="80" cy="62" r="29" fill="#000"/></mask></defs><circle cx="50" cy="86" r="42" fill="${f}" mask="url(#moon)"/>`, eyes: [[28, 76], [41, 74]] },
}

const OUT = 'stroke="#111" stroke-width="1.6" stroke-linejoin="round"'
const PROP_ART = {
  reading: `<g transform="translate(55 70) rotate(-10)"><rect width="32" height="24" rx="2" fill="#f1ede2" ${OUT}/><rect x="4" y="4" width="9" height="8" fill="#8d8d86"/><path d="M16 5h12M16 9h12M4 15h24M4 19h24" stroke="#8d8d86" stroke-width="2"/></g>`,
  editing: `<g transform="translate(57 66) rotate(-8)"><rect width="23" height="28" rx="2" fill="#4b1f5c" ${OUT}/><path d="M12 32 L34 4" stroke="#111" stroke-width="7" stroke-linecap="round"/><path d="M12 32 L34 4" stroke="#e8b21c" stroke-width="4.5" stroke-linecap="round"/></g>`,
  building: `<g transform="translate(54 66)"><path d="M10 7 V2 H24 V7" fill="none" stroke="#111" stroke-width="5"/><path d="M10 7 V2 H24 V7" fill="none" stroke="#9a2a20" stroke-width="2.6"/><rect y="7" width="34" height="19" rx="3" fill="#d6402f" ${OUT}/><rect x="14" y="13" width="6" height="4" fill="#f3c1b9"/></g>`,
  testing: `<g transform="translate(57 70) rotate(-8)"><rect width="26" height="24" rx="2" fill="#f3e27a" ${OUT}/><path d="M6 12 l5 6 l10 -12" fill="none" stroke="#1a1a1a" stroke-width="3.4" stroke-linecap="round" stroke-linejoin="round"/></g>`,
  editor: `<g transform="translate(66 60) rotate(32)"><rect x="-3" y="10" width="7" height="30" rx="2" fill="#2d2d2d" ${OUT}/><rect x="-4.5" y="3" width="10" height="9" fill="#bdbdb6" ${OUT}/><path d="M0.5 -16 C -9 -4, -6 4, 0.5 4 C 7 4, 10 -4, 0.5 -16 Z" fill="#ff7ab8" ${OUT}/></g>`,
  reviewing: `<g transform="translate(58 62)"><path d="M20 20 L32 32" stroke="#111" stroke-width="8" stroke-linecap="round"/><path d="M20 20 L32 32" stroke="#6b4a2a" stroke-width="5" stroke-linecap="round"/><circle cx="13" cy="13" r="11" fill="#cfe9ff" fill-opacity=".85" stroke="#111" stroke-width="5"/><circle cx="13" cy="13" r="11" fill="none" stroke="#9aa3ad" stroke-width="2.4"/></g>`,
  profiling: `<g transform="translate(55 70) rotate(-6)"><rect width="31" height="24" rx="2" fill="#f1ede2" ${OUT}/><path d="M5 19 L12 12 L17 15 L26 6" fill="none" stroke="#2f9a4a" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"/><path d="M21 5 h6 v6" fill="none" stroke="#2f9a4a" stroke-width="3.2" stroke-linecap="round"/></g>`,
  asking: `<g transform="translate(56 64)"><path d="M3 2 h26 a3 3 0 0 1 3 3 v14 a3 3 0 0 1 -3 3 h-15 l-7 6 v-6 h-4 a3 3 0 0 1 -3 -3 v-14 a3 3 0 0 1 3 -3 z" fill="#f4f4ef" ${OUT}/><path d="M12 8 q4 -4 8 0 q2 3 -3 5 v3" fill="none" stroke="#1a1a1a" stroke-width="2.6" stroke-linecap="round"/><circle cx="17" cy="19.5" r="1.6" fill="#1a1a1a"/></g>`,
  idle: `<g transform="translate(60 74)"><circle cx="20" cy="9" r="5.5" fill="none" stroke="#111" stroke-width="5"/><circle cx="20" cy="9" r="5.5" fill="none" stroke="#f4f4ef" stroke-width="2.4"/><rect width="20" height="19" rx="4" fill="#f4f4ef" ${OUT}/><path d="M6 -4 q3 -4 0 -8 M12 -4 q3 -4 0 -8" stroke="#bdbdb6" stroke-width="2" fill="none" stroke-linecap="round"/></g>`,
}

// One worker's avatar as an SVG document: each is drawn isolated, so its ids never clash. A running avatar is drawn in a
// sandboxed frame (for its bob): the desktop wraps the markup in an HTML page of its own, and the browser paints that
// page opaque (white) when the page's colour scheme differs from the app's. Only the page's root decides it, so the
// avatar carries a style sheet that sets the root to "light dark": the page then takes the app's scheme and stays
// transparent around the round badge. In a still image the same rule names the svg itself and changes nothing.
export const FRAME_SCHEME = '<style>:root{color-scheme:light dark;background:transparent}</style>'
/** @param {Kind} kind @param {Prop | null} prop @param {WorkerState} state */
export const avatarSvg = (kind, prop, state) => {
  const look = KINDS[kind]
  const body = BODIES[look.body]
  const eye = look.light ? '#1b1b1b' : '#f6f0e0'
  const eyes = body.eyes.map(([x, y]) => ('tall' in body ? `<rect x="${x - 3}" y="${y - 7}" width="6" height="14" rx="3" fill="${eye}"/>` : `<ellipse cx="${x}" cy="${y}" rx="4.6" ry="6" fill="${eye}"/>`)).join('')
  const bob = state === 'running' ? '<animateTransform attributeName="transform" type="translate" values="0 0;0 -2.5;0 0" dur="1.8s" repeatCount="indefinite"/>' : ''
  const held = prop ? `<g transform="translate(67 75) scale(1.22) translate(-70 -82)">${PROP_ART[prop]}</g>` : ''
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100" style="color-scheme: light dark; background: transparent">${FRAME_SCHEME}<defs><clipPath id="round"><circle cx="50" cy="50" r="43"/></clipPath></defs><circle cx="50" cy="50" r="43" fill="#17181a"/><g clip-path="url(#round)"><g><g transform="translate(50 106) scale(1.32) translate(-50 -106)">${body.shape(look.fill)}${eyes}</g>${held}${bob}</g></g><circle cx="50" cy="50" r="45.5" fill="none" stroke="${STATE_COLOURS[state]}" stroke-width="6"/></svg>`
}

// A prop on its own, for the trail under a finished worker.
/** @param {Prop} prop */
export const propSvg = prop => `<svg xmlns="http://www.w3.org/2000/svg" viewBox="48 50 52 52">${PROP_ART[prop]}</svg>`

